using EqlTracker.Core;
using System.Text.Json;

static class ProgressRewardTests
{
    public static void Register(Action<string,Action> register)
    {
        void Test(string n,Action action)=>register("Progress clarity · "+n,action);
        static void Check(bool value,string reason="Assertion failed"){if(!value)throw new Exception(reason);}
        var cat=Json.Read<Catalog>(Path.Combine(AppContext.BaseDirectory,"data/catalog.json"));
        static QuestNode Node(QuestDefinition q,QuestStep s,string key)=>new(){Kind=QuestNodeKind.Ingredient,Id="node",QuestId=q.Id,StepId=s.Id,ItemKeys=[key],Name="Item"};
        var item=new ItemDefinition{Key="staff",Name="Staff of Elemental Mastery: Water",Sources=[new(){Mob="Phinigel Autropos",Zone="Kedge Keep",Method="Drop",Notes="Kedge Keep - Kill Phinigel Autropos (raid) for Staff of Elemental Mastery: Water",Availability="Preparation guide",WikiUrl="https://example.invalid/a",Revision=1},new(){Mob="Phinigel Autropos",Zone="Kedge Keep",Method="Drop",Availability="Wiki documented",Era="Unverified",WikiUrl="https://example.invalid/b",Revision=2}]};
        var step=new QuestStep{Id="s",Name="Kill [53]Phinigel Autropos in Kedge Keep. Loot Staff of Elemental Mastery: Water.",Instructions="Kill [53]Phinigel Autropos in Kedge Keep. Loot Staff of Elemental Mastery: Water.",Inputs=[new(){ItemKey="staff"}]};var quest=new QuestDefinition{Id="q",Steps=[step]};var catalog=new Catalog{Items=[item]};
        Test("drop facts replace repeated prose and retain qualifications",()=>{var p=ProgressPresentation.Build(Node(quest,step,"staff"),quest,new(),catalog);Check(p.Sources.Count==1&&p.Sources[0].Actor=="Phinigel Autropos"&&p.Sources[0].Zone=="Kedge Keep"&&p.Instructions.Single().Instruction==""&&p.Instructions.Single().Heading=="");Check(p.Sources[0].Additional.Contains("Raid target")&&p.Sources[0].Additional.Contains("Mob level: 53"));Check(p.Sources[0].Evidence.Count==2&&SourcePresentation.Evidence(p.Sources[0].Evidence).Contains("Unverified"));});
        Test("additional requirements are never suppressed",()=>{foreach(string suffix in new[]{" Bring a key."," at night."," and another staff."," until you have two."}){var s=EquipmentPositions.Copy(step);s.Instructions=step.Instructions+suffix;var q=new QuestDefinition{Steps=[s]};var p=ProgressPresentation.Build(Node(q,s,"staff"),q,new(),catalog);Check(p.Instructions.Single().Instruction==s.Instructions,suffix);}});
        Test("different mob zone or method cannot suppress instructions",()=>{foreach(string property in new[]{"Mob","Zone","Method"}){var i=EquipmentPositions.Copy(item);foreach(var source in i.Sources){if(property=="Mob")source.Mob="Another mob";if(property=="Zone")source.Zone="Another zone";if(property=="Method")source.Method="Crafting";}Check(ProgressPresentation.Build(Node(quest,step,"staff"),quest,new(),new(){Items=[i]}).Instructions.Single().Instruction==step.Instructions);}});
        Test("multiple drop routes remain separate",()=>{var i=EquipmentPositions.Copy(item);i.Sources.Add(new(){Mob="Another mob",Zone="Kedge Keep",Method="Drop"});Check(ProgressPresentation.SourcesFor([i.Key],new(){Items=[i]}).Count==2);});
        Test("identical words in distinct steps retain both identities",()=>{var s=EquipmentPositions.Copy(step);s.Id="other";var q=new QuestDefinition{Steps=[step,s]};var p=ProgressPresentation.Build(new(){Kind=QuestNodeKind.Quest},q,new(),catalog);Check(p.Instructions.Count==2&&p.Instructions[0].Step.Id!=p.Instructions[1].Step.Id&&p.Instructions.All(i=>i.Instruction==step.Instructions));});
        Test("craft and turn-in prose and inputs remain intact",()=>{var s=new QuestStep{Id="craft",Name="Make a flute",Instructions="Combine the parts in the forge; give the flute to the bard.",Container="Forge",Inputs=[new(){ItemKey="metal",Count=2}],Outputs=[new(){ItemKey="flute"}]};var q=new QuestDefinition{Steps=[s]};var p=ProgressPresentation.Build(Node(q,s,"flute"),q,new(),new());Check(p.Instructions.Single().Instruction==s.Instructions&&p.Instructions[0].Step.Inputs[0].Count==2&&p.Instructions[0].Step.Container=="Forge");});
        Test("prerequisites retain presentation and completion IDs",()=>{var s=EquipmentPositions.Copy(step);s.Prerequisites=["key"];var prerequisite=new QuestStep{Id="key",Name="Obtain the key",Instructions="Complete the trial."};var q=new QuestDefinition{Steps=[prerequisite,s]};var p=ProgressPresentation.Build(Node(q,s,"staff"),q,new(),catalog);Check(p.Instructions.Any(i=>i.Prerequisite&&i.Step.Id=="key"&&i.Instruction=="Complete the trial."));});
        Test("heading normalization covers whitespace punctuation and partial words",()=>{foreach(string h in new[]{"Give Mahlin's Mystical Bongos to Konia Swiftfoot in Western Karana (guard tower #4), receive Ma","Give Mahlin’s Mystical Bongos to Konia Swiftfoot…"}){var s=new QuestStep{Name=h,Instructions="Give Mahlin's Mystical Bongos to Konia Swiftfoot in Western Karana (guard tower #4), receive Maestro's Symphony Page 24 Bottom."};Check(QuestPresentation.Instruction(null,s).Heading=="");}Check(QuestPresentation.Instruction(null,new(){Name="A distinct title",Instructions="Do the next thing."}).Heading=="A distinct title");});
        Test("all bundled roots steps and prerequisites use one safe projection",()=>{var before=JsonSerializer.Serialize(cat);foreach(var q in cat.Quests){var profile=new CharacterProfile();var active=QuestRecipes.Steps(q,profile);var root=ProgressPresentation.Build(new(){Kind=QuestNodeKind.Quest,Name=q.Name},q,profile,cat);Check(root.Instructions.Count==active.Count);foreach(var block in root.Instructions)Check(block.Heading.Length==0||QuestPresentation.Normalize(block.Heading)!=QuestPresentation.Normalize(block.Instruction),q.Name);foreach(var s in active)foreach(string key in s.Outputs.Select(i=>i.ItemKey).Concat(s.Inputs.Select(i=>i.ItemKey)).DefaultIfEmpty("")){var p=ProgressPresentation.Build(Node(q,s,key),q,profile,cat);Check(p.Instructions.Any(i=>i.Step.Id==s.Id&&!i.Prerequisite));}}Check(before==JsonSerializer.Serialize(cat));});
        Test("full checklist preserves inactive routes",()=>{foreach(var q in cat.Quests){var p=ProgressPresentation.Build(new(){Kind=QuestNodeKind.Quest},q,new(),cat,allRoutes:true);Check(p.Instructions.Count==q.Steps.Count);}});
        Test("reward alternatives retain all stable item keys",()=>{var q=new QuestDefinition{RewardKey="a",RewardAlternatives=[["a","b"],["c"]]};Check(QuestPresentation.RewardKeys(q).SequenceEqual(new[]{"a","b","c"}));});
    }
}
